/// <summary>
/// When <c>WHSWorkExecuteDisplayMovementByTempateUseFullLPMovementForLocationFlight</c> is enabled, automatic move LP policy will create work only when LP is entered and is not empty. 
/// If a location is entered, the user will need to enter all required fields to proceed. 
/// </summary>
internal final class WHSWorkExecuteDisplayMovementByTempateUseFullLPMovementForLocationFlight extends Flight
{
    private static WHSWorkExecuteDisplayMovementByTempateUseFullLPMovementForLocationFlight singleton = new WHSWorkExecuteDisplayMovementByTempateUseFullLPMovementForLocationFlight();

}
